package cn.yuanxin.mvp.web.error;

import org.springframework.http.HttpStatus;

/**
 * 稳定业务原因码（DD 3.2 错误码表 + 基础层扩展 NOT_IMPLEMENTED + 500 INTERNAL）。
 *
 * <p>枚举取值与 backend/contracts/openapi/openapi.yaml components.schemas.ErrorCode
 * 一致（INTERNAL 在 OpenAPI ErrorEnvelope 响应用散文描述，500 样例见 DD 3.2）；
 * INTERNAL 只用于未映射异常，不出现在业务端点 x-error-codes 中。</p>
 *
 * <p>retryable 语义（digest §3 / DD 3.2 重试动作列）：429/503/504 与
 * REQUEST_IN_PROGRESS（同逻辑键等待重试）为 true；其余为 false。
 * INTERNAL 取 false——未知异常不承诺重试安全，客户端按 requestId 诊断。</p>
 */
public enum ErrorCode {
    // 400 / 413 / 415 / 422
    INVALID_INPUT(HttpStatus.BAD_REQUEST, false),
    UPLOAD_TOO_LARGE(HttpStatus.PAYLOAD_TOO_LARGE, false),
    UNSUPPORTED_IMAGE(HttpStatus.UNSUPPORTED_MEDIA_TYPE, false),
    FACE_QUALITY_REJECTED(HttpStatus.UNPROCESSABLE_ENTITY, false),
    // 401
    AUTH_REQUIRED(HttpStatus.UNAUTHORIZED, false),
    SESSION_INVALID(HttpStatus.UNAUTHORIZED, false),
    // 403 / 404
    RESOURCE_NOT_VISIBLE(HttpStatus.NOT_FOUND, false),
    CALLER_NOT_ALLOWED(HttpStatus.FORBIDDEN, false),
    FACE_NOT_VERIFIED(HttpStatus.FORBIDDEN, false),
    GRANT_REVOKED(HttpStatus.FORBIDDEN, false),
    // 409
    IDEMPOTENCY_CONTENT_CONFLICT(HttpStatus.CONFLICT, false),
    BINDING_CHANGED(HttpStatus.CONFLICT, false),
    TASK_REPLACED(HttpStatus.CONFLICT, false),
    PHOTO_VERSION_CONFLICT(HttpStatus.CONFLICT, false),
    DEVICE_OCCUPIED(HttpStatus.CONFLICT, false),
    PLAN_NOT_READY(HttpStatus.CONFLICT, false),
    PLAN_COMPLETED(HttpStatus.CONFLICT, false),
    EXECUTION_NOT_RESUMABLE(HttpStatus.CONFLICT, false),
    RECORD_CONFLICT(HttpStatus.CONFLICT, false),
    CLOSURE_GAPS(HttpStatus.CONFLICT, false),
    STOP_NOT_CONFIRMED(HttpStatus.CONFLICT, false),
    BOUND_TO_OTHER(HttpStatus.CONFLICT, false),
    REQUEST_IN_PROGRESS(HttpStatus.CONFLICT, true),
    // 429 / 503 / 504 / 500 / 501
    RATE_LIMITED(HttpStatus.TOO_MANY_REQUESTS, true),
    DEPENDENCY_UNAVAILABLE(HttpStatus.SERVICE_UNAVAILABLE, true),
    DEPENDENCY_TIMEOUT(HttpStatus.GATEWAY_TIMEOUT, true),
    INTERNAL(HttpStatus.INTERNAL_SERVER_ERROR, false),
    UNSUPPORTED_CONTRACT(HttpStatus.UNPROCESSABLE_ENTITY, false),
    NOT_IMPLEMENTED(HttpStatus.NOT_IMPLEMENTED, false);

    private final HttpStatus defaultStatus;
    private final boolean defaultRetryable;

    ErrorCode(HttpStatus defaultStatus, boolean defaultRetryable) {
        this.defaultStatus = defaultStatus;
        this.defaultRetryable = defaultRetryable;
    }

    public HttpStatus defaultStatus() {
        return defaultStatus;
    }

    public boolean defaultRetryable() {
        return defaultRetryable;
    }
}

package cn.yuanxin.mvp.web.error;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

/**
 * 结构化业务异常（错误信封的唯一生产路径）。
 *
 * <p>携带 code / HTTP 状态 / retryable / details（只含调用方可见的冲突字段、
 * 缺失序号等；不泄露供应商诊断、堆栈、人脸候选）与附加响应头
 * （如 REQUEST_IN_PROGRESS 的 Retry-After）。</p>
 */
public class ApiException extends RuntimeException {

    private final ErrorCode code;
    private final int httpStatus;
    private final boolean retryable;
    private final Map<String, Object> details;
    private final Map<String, String> headers;

    public ApiException(ErrorCode code, String message) {
        this(code, code.defaultStatus().value(), code.defaultRetryable(), message, null, null);
    }

    public ApiException(ErrorCode code, String message, Map<String, Object> details) {
        this(code, code.defaultStatus().value(), code.defaultRetryable(), message, details, null);
    }

    public ApiException(ErrorCode code, int httpStatus, String message,
                        Map<String, Object> details, Map<String, String> headers) {
        this(code, httpStatus, code.defaultRetryable(), message, details, headers);
    }

    public ApiException(ErrorCode code, int httpStatus, boolean retryable, String message,
                        Map<String, Object> details, Map<String, String> headers) {
        super(message, null, true, false); // 不进客户端；堆栈只留在服务端日志（advice 记录）
        this.code = Objects.requireNonNull(code);
        this.httpStatus = httpStatus;
        this.retryable = retryable;
        this.details = details == null ? null : Collections.unmodifiableMap(new LinkedHashMap<>(details));
        this.headers = headers == null ? Map.of() : Collections.unmodifiableMap(new LinkedHashMap<>(headers));
    }

    public ErrorCode getCode() {
        return code;
    }

    public int getHttpStatus() {
        return httpStatus;
    }

    public boolean isRetryable() {
        return retryable;
    }

    public Map<String, Object> getDetails() {
        return details;
    }

    public Map<String, String> getHeaders() {
        return headers;
    }

    /** 带 Retry-After 秒数的 REQUEST_IN_PROGRESS。 */
    public static ApiException requestInProgress(long retryAfterSeconds) {
        long ra = Math.max(1, retryAfterSeconds);
        return new ApiException(ErrorCode.REQUEST_IN_PROGRESS,
                ErrorCode.REQUEST_IN_PROGRESS.defaultStatus().value(),
                "previous attempt still in progress; retry with the same Idempotency-Key after Retry-After",
                Map.of("retryAfterSeconds", ra),
                Map.of("Retry-After", String.valueOf(ra)));
    }
}

package cn.yuanxin.mvp.web.web;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.Map;

/**
 * 成功响应信封（contracts/openapi/openapi.yaml components.schemas.SuccessEnvelope）：
 * {@code {requestId, data, meta:{replayed, serverTime}}}。
 *
 * <p>204 不携带本信封（requestId 走 X-Request-Id 头，见 RequestIdFilter）。</p>
 */
public record SuccessEnvelope(String requestId, Object data, Meta meta) {

    public record Meta(boolean replayed, String serverTime, Map<String, Object> extra) {
        @JsonInclude(JsonInclude.Include.NON_NULL)
        public Meta {
        }
    }

    public static SuccessEnvelope of(String requestId, Object data, boolean replayed, String serverTime) {
        return new SuccessEnvelope(requestId, data, new Meta(replayed, serverTime, null));
    }
}

package cn.yuanxin.mvp.web.web;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.Map;

/**
 * 错误响应信封（contracts ErrorEnvelope）：
 * {@code {requestId, error:{code, message, retryable, details?}}}。
 *
 * <p>details 只含调用方可见的冲突字段/缺失序号；不泄露归属、人脸候选、
 * 供应商诊断、堆栈（DD 3.2、A/decisions #15）。</p>
 */
public record ErrorEnvelope(String requestId, ErrorBody error) {

    public record ErrorBody(String code, String message, boolean retryable,
                            @JsonInclude(JsonInclude.Include.NON_NULL) Map<String, Object> details) {
    }

    public static ErrorEnvelope of(String requestId, String code, String message,
                                   boolean retryable, Map<String, Object> details) {
        return new ErrorEnvelope(requestId, new ErrorBody(code, message, retryable, details));
    }
}

package cn.yuanxin.mvp.web.web;

/**
 * 成功响应信封（contracts/openapi/openapi.yaml components.schemas.SuccessEnvelope）：
 * {@code {requestId, data, meta:{replayed, serverTime}}}。
 *
 * <p>204 不携带本信封（requestId 走 X-Request-Id 头，见 RequestIdFilter）。
 * meta 容忍新增字段（契约 EnvelopeMeta additionalProperties:true）；
 * data 由各端点显式给出（列表端点用 {@link ListData}）。</p>
 */
public record SuccessEnvelope(String requestId, Object data, Meta meta) {

    /** @param replayed true 表示本响应来自 T13 幂等重放（原业务结果，不重做写入） */
    public record Meta(boolean replayed, String serverTime) {
    }

    public static SuccessEnvelope of(String requestId, Object data, boolean replayed, String serverTime) {
        return new SuccessEnvelope(requestId, data, new Meta(replayed, serverTime));
    }
}

package cn.yuanxin.mvp.web.web;

import java.util.List;

/**
 * 列表响应 data 形状（契约 ListData）：{@code {items, nextCursor}}。
 * nextCursor 为 null 表示无后续页（字段保留，不省略）。
 */
public record ListData<T>(List<T> items, String nextCursor) {
}

package cn.yuanxin.mvp.web.web;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.slf4j.MDC;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;
import java.util.UUID;

/**
 * 每次 HTTP 尝试生成服务端 requestId（不信任入站 X-Request-Id，一律服务端生成；
 * DD 3.1「追踪」）：写入 request 属性 + MDC（结构化日志关联），并保证
 * 所有响应（含错误、含 204、含 actuator）都带 X-Request-Id 头。
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class RequestIdFilter extends OncePerRequestFilter {

    public static final String ATTR_REQUEST_ID = "mvp.requestId";
    public static final String HEADER = "X-Request-Id";
    public static final String MDC_KEY = "requestId";

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                    FilterChain chain) throws ServletException, IOException {
        String requestId = UUID.randomUUID().toString();
        request.setAttribute(ATTR_REQUEST_ID, requestId);
        response.setHeader(HEADER, requestId);
        MDC.put(MDC_KEY, requestId);
        try {
            chain.doFilter(request, response);
        } finally {
            MDC.remove(MDC_KEY);
        }
    }
}

package cn.yuanxin.mvp.web.web;

import jakarta.servlet.http.HttpServletRequest;
import org.springframework.stereotype.Component;

import java.time.Instant;
import java.time.temporal.ChronoUnit;

/**
 * 信封构造辅助：requestId 取自 RequestIdFilter 属性；replayed 取自 T13
 * 重放标记（请求属性）；serverTime 为 RFC3339 UTC（秒精度）。
 */
@Component
public class EnvelopeSupport {

    /** T13 succeeded 重放时由控制器置 true，信封 meta.replayed 读取。 */
    public static final String ATTR_REPLAYED = "mvp.replayed";

    public static String requestId(HttpServletRequest request) {
        Object v = request.getAttribute(RequestIdFilter.ATTR_REQUEST_ID);
        return v == null ? "" : v.toString();
    }

    public static String rfc3339(Instant instant) {
        return instant.truncatedTo(ChronoUnit.SECONDS).toString();
    }

    public SuccessEnvelope ok(HttpServletRequest request, Object data) {
        boolean replayed = Boolean.TRUE.equals(request.getAttribute(ATTR_REPLAYED));
        return SuccessEnvelope.of(requestId(request), data, replayed, rfc3339(Instant.now()));
    }

    public SuccessEnvelope ok(HttpServletRequest request, Object data, boolean explicitReplayed) {
        return SuccessEnvelope.of(requestId(request), data, explicitReplayed, rfc3339(Instant.now()));
    }

    public ErrorEnvelope error(HttpServletRequest request, ErrorEnvelope.ErrorBody body) {
        return new ErrorEnvelope(requestId(request), body);
    }
}

package cn.yuanxin.mvp.web.auth;

/** 认证主体类型：APP（手机号会话）或 GIMBAL（云台设备会话）。 */
public enum PrincipalType {
    APP,
    GIMBAL
}

package cn.yuanxin.mvp.web.auth;

import java.util.UUID;

/**
 * 请求内认证主体上下文（ARCH 6.1；digest §6）。
 *
 * <p>身份只由服务端会话（token）派生——请求体声明的 accountId/gimbalId
 * 一律不作为认证依据（fail closed 规则）。APP 主体填 accountUuid +
 * installationId + sessionId；GIMBAL 主体填 gimbalUuid + credentialVersion +
 * sessionId。credentialVersion 为 DB bigint，Java 内以 long 表示，出 JSON
 * 时按契约转十进制字符串。</p>
 *
 * <p>控制器通过 {@link PrincipalContextArgumentResolver} 以方法参数注入
 * （由 BearerAuthFilter 在认证成功时写入 request 属性）。</p>
 */
public record PrincipalContext(
        PrincipalType principalType,
        UUID accountUuid,
        String installationId,
        UUID gimbalUuid,
        long credentialVersion,
        String sessionId,
        String requestId) {

    public static PrincipalContext forApp(AuthenticatedPrincipal p, String requestId) {
        return new PrincipalContext(PrincipalType.APP, p.accountUuid(), p.installationId(),
                null, 0, p.sessionId(), requestId);
    }

    public static PrincipalContext forGimbal(AuthenticatedPrincipal p, String requestId) {
        return new PrincipalContext(PrincipalType.GIMBAL, null, null,
                p.gimbalUuid(), p.credentialVersion(), p.sessionId(), requestId);
    }

    /**
     * T13 principal_id 规范文本（contracts/decisions-notes.md §2；A/decisions #2）：
     * app_account = "&lt;account_uuid&gt;:&lt;installation_id&gt;"；gimbal = "&lt;gimbal_uuid&gt;"。
     */
    public String t13PrincipalId() {
        return switch (principalType) {
            case APP -> accountUuid + ":" + installationId;
            case GIMBAL -> String.valueOf(gimbalUuid);
        };
    }

    /** T13 principal_type 列取值。 */
    public String t13PrincipalType() {
        return switch (principalType) {
            case APP -> "app_account";
            case GIMBAL -> "gimbal";
        };
    }
}

package cn.yuanxin.mvp.web.auth;

import java.time.Instant;
import java.util.UUID;

/**
 * 会话提供方认证通过后返回的主体快照（服务端派生，绝不来自请求体声明）。
 * APP 会话填 accountUuid/installationId；GIMBAL 会话填 gimbalUuid/credentialVersion。
 */
public record AuthenticatedPrincipal(
        PrincipalType principalType,
        UUID accountUuid,
        String installationId,
        UUID gimbalUuid,
        long credentialVersion,
        String sessionId) {

    public static AuthenticatedPrincipal app(UUID accountUuid, String installationId, String sessionId) {
        return new AuthenticatedPrincipal(PrincipalType.APP, accountUuid, installationId, null, 0, sessionId);
    }

    public static AuthenticatedPrincipal gimbal(UUID gimbalUuid, long credentialVersion, String sessionId) {
        return new AuthenticatedPrincipal(PrincipalType.GIMBAL, null, null, gimbalUuid, credentialVersion, sessionId);
    }
}

package cn.yuanxin.mvp.web.auth;

import java.time.Instant;
import java.util.Optional;
import java.util.UUID;

/**
 * APP/GIMBAL 会话提供方适配端口（DD 4.1/4.2；digest §6）。
 *
 * <p>会话存储表不存在于 14 表设计（不擅自加表）——真实实现由未来选定的
 * 认证提供方承担；dev/test 使用内存隔离替身 {@code InMemorySessionDouble}。</p>
 *
 * <p>核心安全约束：{@link #authenticate(String)} 只接受本提供方自己签发的
 * token；任意字符串（包括猜测的 accountId/installationId）绝不认证成功。</p>
 */
public interface SessionProvider {

    /** token → 主体快照；非本提供方签发/已撤销/过期 → empty。 */
    Optional<AuthenticatedPrincipal> authenticate(String accessToken);

    /** 手机号会话签发（challenge+code 验证并 find-or-create 本地账号后调用）。 */
    IssuedAppSession createAppSession(UUID accountId, String installationId);

    /** 刷新：旧凭据换新凭据（轮换与旧凭据撤销由提供方协议保证）。 */
    Optional<IssuedAppSession> refreshAppSession(String refreshCredential);

    /** 撤销当前会话（退出登录）。返回被撤销会话的主体信息供 T09 失效。 */
    Optional<RevokedSession> revokeSession(String accessToken);

    /** 云台设备会话签发（M2-A01；DeviceCredentialProvider 验证通过后调用）。 */
    IssuedGimbalSession createGimbalSession(UUID gimbalId, long credentialVersion);

    record IssuedAppSession(String accessToken, String refreshToken, UUID accountId,
                            String installationId, Instant expiresAt) {
    }

    record IssuedGimbalSession(String sessionToken, UUID gimbalId, long credentialVersion,
                               Instant expiresAt) {
    }

    /** sessionId 同时作为 T09 notification_destinations.session_ref 的匹配值。 */
    record RevokedSession(UUID accountId, String installationId, String sessionId) {
    }
}

package cn.yuanxin.mvp.web.auth;

import java.util.Optional;
import java.util.UUID;

/**
 * 云台设备凭据验证端口（DD 4.2；M2-A01）。
 * 验证设备凭据 → 可信云台身份（gimbalId + 当前 credential_version）。
 * 验证失败绝不登记为可信在线（fail closed）。
 */
public interface DeviceCredentialProvider {

    Optional<GimbalIdentity> verify(String credential, long credentialVersion, String proof);

    record GimbalIdentity(UUID gimbalId, String serialNo, long credentialVersion) {
    }
}

package cn.yuanxin.mvp.web.auth;

import java.util.Optional;

/**
 * 短信验证码挑战端口（DD 4.1）。提供方负责验证码生命周期与风控；
 * 不泄露账号是否已存在。真实供应商未选定——替身仅 dev/test。
 */
public interface SmsCodeProvider {

    /** 发起挑战：返回 challengeId 与建议重试等待秒数。 */
    ChallengeOutcome issue(String phone, String purpose);

    /**
     * 验证 challengeId + code；成功返回服务端规范化的 login_subject（手机号）。
     * 失败返回 empty（不区分"错码"与"无挑战"，避免探测）。
     */
    Optional<String> verify(String challengeId, String code);

    record ChallengeOutcome(String challengeId, int retryAfterSeconds) {
    }
}

package cn.yuanxin.mvp.web.auth;

/**
 * 人脸适配端口分类结果（DD 4.x；digest §6）：已匹配/可靠新人员/不确定/
 * 质量不合格/依赖失败。A 包只定义端口与替身，无业务调用点（B/D 接线）。
 */
public enum FaceClassification {
    MATCHED,
    RELIABLE_NEW,
    UNCERTAIN,
    QUALITY_REJECTED,
    /** 依赖失败 ≠ 匹配成功（fail closed：人脸超时/异常绝不按通过处理）。 */
    DEPENDENCY_FAILED
}

package cn.yuanxin.mvp.web.auth;

/**
 * 人脸提供方适配端口（digest §6：Java 请求内同步调用，不排队列）。
 * A 包仅端口 + 替身；真实供应商（阿里云 PoC/腾讯云对照）未选定。
 */
public interface FaceProvider {

    /**
     * 对受控媒体内容做同步分类。
     *
     * @param purpose 采集用途（grant/admission/revalidation/assessment 文本）
     * @param content 图片原始字节（调用方已从 StoragePort 读出）
     */
    FaceClassification classify(String purpose, byte[] content);
}

package cn.yuanxin.mvp.web.media;

import java.io.InputStream;

/**
 * 对象存储适配端口（digest §6 OSS 适配端口 / §7）。私有对象、purpose 驱动、
 * Web/Worker 最小权限凭据；PG 只存引用/归属，不存二进制。
 *
 * <p>dev/test 替身 = 本地文件系统（FileSystemStorageDouble）；
 * 生产 fail closed：无真实实现则启动失败（ProductionFailClosedValidator）。</p>
 */
public interface StoragePort {

    /** 写入对象（流式；实现负责限制大小与异常时清理临时状态）。 */
    void put(String objectKey, InputStream content, long byteSize, String contentType);

    /** 流式读取（对象不存在返回 null；调用方负责关闭）。 */
    InputStream getStream(String objectKey);

    byte[] get(String objectKey);

    boolean exists(String objectKey);

    void delete(String objectKey);
}

package cn.yuanxin.mvp.web.media;

/**
 * T11 media_objects.purpose 枚举（V1 迁移 CHECK 取值；digest §2 T11）。
 */
public enum MediaPurpose {
    ASSESSMENT_SOURCE("assessment_source"),
    ASSESSMENT_RESULT("assessment_result"),
    GRANT_FACE("grant_face"),
    EXECUTION_FACE("execution_face"),
    REVALIDATION_FACE("revalidation_face");

    private final String dbValue;

    MediaPurpose(String dbValue) {
        this.dbValue = dbValue;
    }

    public String dbValue() {
        return dbValue;
    }

    public static MediaPurpose fromDbValue(String v) {
        for (MediaPurpose p : values()) {
            if (p.dbValue.equals(v)) return p;
        }
        throw new IllegalArgumentException("unknown media purpose: " + v);
    }
}

package cn.yuanxin.mvp.web.auth;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import cn.yuanxin.mvp.web.web.EnvelopeSupport;
import cn.yuanxin.mvp.web.web.ErrorEnvelope;
import cn.yuanxin.mvp.web.web.RequestIdFilter;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.slf4j.MDC;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;
import java.util.Optional;
import java.util.Set;

/**
 * Bearer 认证过滤器：保护 /api/**，除公开清单（无 Bearer 的基础认证端点）。
 * actuator 不在 /api/** 下 → 开放。
 *
 * <p>身份只从 token 派生：请求体里的 accountId/installationId/gimbalId 字段
 * 一律不作为认证依据（fail closed；digest §6）。缺失 Authorization →
 * 401 AUTH_REQUIRED；token 非本提供方签发/已撤销/过期 → 401 SESSION_INVALID。</p>
 *
 * <p>501 业务 stub 在本过滤器之后执行：未认证请求先拿到 401（证明业务路径
 * 的无效认证拒绝），已认证请求拿到 501 NOT_IMPLEMENTED。</p>
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE + 10)
public class BearerAuthFilter extends OncePerRequestFilter {

    public static final String ATTR_PRINCIPAL = "mvp.principal";

    /** 公开（无 Bearer）端点：method + 精确 path。 */
    private static final Set<String> PUBLIC = Set.of(
            "POST /api/v1/auth/sms-challenges",
            "POST /api/v1/auth/sessions",
            "POST /api/v1/auth/session-refreshes",
            "POST /api/v1/gimbal-sessions");

    private final SessionProvider sessionProvider;
    private final ObjectMapper objectMapper;

    public BearerAuthFilter(SessionProvider sessionProvider, ObjectMapper objectMapper) {
        this.sessionProvider = sessionProvider;
        this.objectMapper = objectMapper;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                    FilterChain chain) throws ServletException, IOException {
        String path = request.getRequestURI();
        if (!path.startsWith("/api/") || PUBLIC.contains(request.getMethod() + " " + path)) {
            chain.doFilter(request, response);
            return;
        }
        String header = request.getHeader("Authorization");
        if (header == null || !header.startsWith("Bearer ") || header.substring(7).isBlank()) {
            reject(response, ErrorCode.AUTH_REQUIRED, "missing bearer token");
            return;
        }
        String token = header.substring(7);
        Optional<AuthenticatedPrincipal> principal = sessionProvider.authenticate(token);
        if (principal.isEmpty()) {
            reject(response, ErrorCode.SESSION_INVALID, "session token invalid or expired");
            return;
        }
        AuthenticatedPrincipal p = principal.get();
        String requestId = String.valueOf(
                request.getAttribute(RequestIdFilter.ATTR_REQUEST_ID) == null
                        ? "" : request.getAttribute(RequestIdFilter.ATTR_REQUEST_ID));
        PrincipalContext ctx = switch (p.principalType()) {
            case APP -> PrincipalContext.forApp(p, requestId);
            case GIMBAL -> PrincipalContext.forGimbal(p, requestId);
        };
        request.setAttribute(ATTR_PRINCIPAL, ctx);
        MDC.put("principalType", p.principalType().name());
        MDC.put("principalRef", ctx.t13PrincipalId());
        try {
            chain.doFilter(request, response);
        } finally {
            MDC.remove("principalType");
            MDC.remove("principalRef");
        }
    }

    private void reject(HttpServletResponse response, ErrorCode code, String message) throws IOException {
        // ApiException → 信封字段统一走 code 默认值（401 不可重试）
        ApiException ex = new ApiException(code, message);
        String requestId = MDC.get(RequestIdFilter.MDC_KEY);
        ErrorEnvelope body = ErrorEnvelope.of(requestId == null ? "" : requestId,
                code.name(), ex.getMessage(), ex.isRetryable(), null);
        response.setStatus(HttpStatus.UNAUTHORIZED.value());
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        response.setCharacterEncoding("UTF-8");
        objectMapper.writeValue(response.getOutputStream(), body);
    }
}

package cn.yuanxin.mvp.web.auth;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.core.MethodParameter;
import org.springframework.stereotype.Component;
import org.springframework.web.bind.support.WebDataBinderFactory;
import org.springframework.web.context.request.NativeWebRequest;
import org.springframework.web.method.support.HandlerMethodArgumentResolver;
import org.springframework.web.method.support.ModelAndViewContainer;

/**
 * 把 BearerAuthFilter 写入的 {@link PrincipalContext} 解析为控制器方法参数。
 * 公开端点的控制器不得声明该参数；缺失时以 401 防御（理论上不可达——
 * 过滤器已拦截，此处仅为编程错误兜底）。
 */
@Component
public class PrincipalContextArgumentResolver implements HandlerMethodArgumentResolver {

    @Override
    public boolean supportsParameter(MethodParameter parameter) {
        return PrincipalContext.class.equals(parameter.getParameterType());
    }

    @Override
    public Object resolveArgument(MethodParameter parameter, ModelAndViewContainer mavContainer,
                                  NativeWebRequest webRequest, WebDataBinderFactory binderFactory) {
        HttpServletRequest request = webRequest.getNativeRequest(HttpServletRequest.class);
        Object v = request.getAttribute(BearerAuthFilter.ATTR_PRINCIPAL);
        if (!(v instanceof PrincipalContext ctx)) {
            throw new ApiException(ErrorCode.AUTH_REQUIRED, "authenticated principal required");
        }
        return ctx;
    }
}

package cn.yuanxin.mvp.web.web;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import cn.yuanxin.mvp.web.idempotency.StaleAttemptException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.ConstraintViolation;
import jakarta.validation.ConstraintViolationException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.BeanPropertiesBindingResult;
import org.springframework.validation.FieldError;
import org.springframework.web.HttpMediaTypeNotSupportedException;
import org.springframework.web.HttpRequestMethodNotSupportedException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.MissingRequestHeaderException;
import org.springframework.web.bind.MissingServletRequestParameterException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.HandlerMethodValidationException;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
import org.springframework.web.multipart.MaxUploadSizeExceededException;
import org.springframework.web.servlet.resource.NoResourceFoundException;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 全局异常 → 标准错误信封（DD 3.2；decisions #15）：
 * <ul>
 *   <li>ApiException → 其自带 code/status/retryable/details/headers（如 Retry-After）；</li>
 *   <li>Bean Validation / 类型转换 / 非法游标 → 400 INVALID_INPUT，
 *       details.fields 列出违规字段（仅调用方可见信息）；</li>
 *   <li>请求体 JSON 不可读（含 Jackson STRICT_DUPLICATE_DETECTION 拒绝的重复键）
 *       → 400 INVALID_INPUT；</li>
 *   <li>未映射路径 → 404 RESOURCE_NOT_VISIBLE（不泄露存在性）；</li>
 *   <li>StaleAttemptException（T13 代次守卫：接管已发生，本尝试的业务写已随
 *       事务回滚）→ 409 REQUEST_IN_PROGRESS + Retry-After（裁量：按"同键稍后
 *       重试"语义，而非 500）；</li>
 *   <li>其余一切 → 500 INTERNAL：堆栈只进服务端日志，客户端只见 requestId。</li>
 * </ul>
 * 405/415 无对应契约错误码，映射为 400 INVALID_INPUT（客户端调用错误，非服务端故障）。
 */
@RestControllerAdvice(basePackages = "cn.yuanxin.mvp.web")
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    private final EnvelopeSupport envelopes;
    private final ObjectMapper objectMapper;

    public GlobalExceptionHandler(EnvelopeSupport envelopes, ObjectMapper objectMapper) {
        this.envelopes = envelopes;
        this.objectMapper = objectMapper;
    }

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> apiException(ApiException ex, HttpServletRequest request) {
        return render(request, ex.getCode().name(), ex.getMessage(), ex.isRetryable(),
                ex.getDetails(), ex.getHttpStatus(), ex.getHeaders());
    }

    @ExceptionHandler(StaleAttemptException.class)
    public ResponseEntity<Map<String, Object>> staleAttempt(StaleAttemptException ex,
                                                            HttpServletRequest request) {
        log.warn("stale idempotency attempt rejected (business tx rolled back): {}", ex.getMessage());
        return render(request, ErrorCode.REQUEST_IN_PROGRESS.name(),
                "idempotency attempt was taken over; business changes rolled back", true,
                null, HttpStatus.CONFLICT.value(), Map.of("Retry-After", "1"));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, Object>> validation(MethodArgumentNotValidException ex,
                                                          HttpServletRequest request) {
        List<Map<String, Object>> fields = new ArrayList<>();
        for (FieldError fe : ex.getBindingResult().getFieldErrors()) {
            fields.add(fieldEntry(fe.getField(), fe.getDefaultMessage()));
        }
        for (var ce : ex.getBindingResult().getGlobalErrors()) {
            fields.add(fieldEntry(ce.getObjectName(), ce.getDefaultMessage()));
        }
        return invalidInput(request, fields);
    }

    @ExceptionHandler(HandlerMethodValidationException.class)
    public ResponseEntity<Map<String, Object>> methodValidation(HandlerMethodValidationException ex,
                                                                HttpServletRequest request) {
        List<Map<String, Object>> fields = new ArrayList<>();
        ex.getAllValidationResults().forEach(r -> r.getResolvableErrors().forEach(e ->
                fields.add(fieldEntry(e instanceof FieldError fe ? fe.getField()
                        : r.getMethodParameter().getParameterName(), e.getDefaultMessage()))));
        return invalidInput(request, fields);
    }

    @ExceptionHandler(ConstraintViolationException.class)
    public ResponseEntity<Map<String, Object>> constraintViolation(ConstraintViolationException ex,
                                                                   HttpServletRequest request) {
        List<Map<String, Object>> fields = new ArrayList<>();
        for (ConstraintViolation<?> v : ex.getConstraintViolations()) {
            fields.add(fieldEntry(v.getPropertyPath().toString(), v.getMessage()));
        }
        return invalidInput(request, fields);
    }

    @ExceptionHandler({HttpMessageNotReadableException.class,
            MissingServletRequestParameterException.class,
            MissingRequestHeaderException.class,
            MethodArgumentTypeMismatchException.class,
            IllegalArgumentException.class})
    public ResponseEntity<Map<String, Object>> badInput(Exception ex, HttpServletRequest request) {
        String reason = switch (ex) {
            case HttpMessageNotReadableException e -> "malformed_json";
            case MissingServletRequestParameterException e -> "missing_parameter:" + e.getParameterName();
            case MissingRequestHeaderException e -> "missing_header:" + e.getHeaderName();
            case MethodArgumentTypeMismatchException e -> "bad_parameter:" + e.getName();
            default -> "invalid_argument";
        };
        log.debug("rejected request input ({}): {}", reason, ex.getMessage());
        return render(request, ErrorCode.INVALID_INPUT.name(), "invalid request input",
                false, Map.of("reason", reason), HttpStatus.BAD_REQUEST.value(), Map.of());
    }

    @ExceptionHandler(CursorException.class)
    public ResponseEntity<Map<String, Object>> badCursor(CursorException ex, HttpServletRequest request) {
        return render(request, ErrorCode.INVALID_INPUT.name(), ex.getMessage(), false,
                Map.of("reason", "invalid_cursor"), HttpStatus.BAD_REQUEST.value(), Map.of());
    }

    @ExceptionHandler(MaxUploadSizeExceededException.class)
    public ResponseEntity<Map<String, Object>> tooLarge(MaxUploadSizeExceededException ex,
                                                        HttpServletRequest request) {
        return render(request, ErrorCode.UPLOAD_TOO_LARGE.name(), "upload exceeds configured limit",
                false, null, HttpStatus.PAYLOAD_TOO_LARGE.value(), Map.of());
    }

    @ExceptionHandler({HttpRequestMethodNotSupportedException.class,
            HttpMediaTypeNotSupportedException.class})
    public ResponseEntity<Map<String, Object>> methodOrMedia(Exception ex, HttpServletRequest request) {
        return render(request, ErrorCode.INVALID_INPUT.name(), "unsupported request shape", false,
                Map.of("reason", ex instanceof HttpRequestMethodNotSupportedException
                        ? "method_not_allowed" : "unsupported_media_type"),
                HttpStatus.BAD_REQUEST.value(), Map.of());
    }

    @ExceptionHandler(NoResourceFoundException.class)
    public ResponseEntity<Map<String, Object>> notFound(NoResourceFoundException ex,
                                                        HttpServletRequest request) {
        // 统一 404 RESOURCE_NOT_VISIBLE：不泄露资源是否存在（DD 3.2）
        return render(request, ErrorCode.RESOURCE_NOT_VISIBLE.name(), "resource not visible",
                false, null, HttpStatus.NOT_FOUND.value(), Map.of());
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, Object>> unexpected(Exception ex, HttpServletRequest request) {
        log.error("unhandled exception on {} {}", request.getMethod(), request.getRequestURI(), ex);
        return render(request, ErrorCode.INTERNAL.name(), "internal server error",
                false, null, HttpStatus.INTERNAL_SERVER_ERROR.value(), Map.of());
    }

    private ResponseEntity<Map<String, Object>> invalidInput(HttpServletRequest request,
                                                             List<Map<String, Object>> fields) {
        Map<String, Object> details = new LinkedHashMap<>();
        details.put("fields", fields);
        return render(request, ErrorCode.INVALID_INPUT.name(), "request validation failed",
                false, details, HttpStatus.BAD_REQUEST.value(), Map.of());
    }

    private Map<String, Object> fieldEntry(String field, String reason) {
        Map<String, Object> m = new LinkedHashMap<>();
        m.put("field", field);
        m.put("reason", reason == null ? "invalid" : reason);
        return m;
    }

    private ResponseEntity<Map<String, Object>> render(HttpServletRequest request, String code,
                                                       String message, boolean retryable,
                                                       Map<String, Object> details, int status,
                                                       Map<String, String> headers) {
        ErrorEnvelope body = envelopes.error(request,
                new ErrorEnvelope.ErrorBody(code, message, retryable, details));
        // 保证无循环序列化风险：信封转普通 Map 输出
        Map<String, Object> map = objectMapper.convertValue(body, Map.class);
        ResponseEntity.Builder<Map<String, Object>> builder =
                ResponseEntity.status(status).body(map);
        headers.forEach(builder::header);
        return builder.build();
    }
}

package cn.yuanxin.mvp.web.web;

/** 非法游标 → 400 INVALID_INPUT（reason=invalid_cursor；契约 Cursor 参数说明）。 */
public class CursorException extends RuntimeException {
    public CursorException(String message) {
        super(message, null, true, false);
    }
}

package cn.yuanxin.mvp.web.web;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Component;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

/**
 * 不透明游标编解码（契约公共规则：limit 默认 20 上限 100；cursor 绑定
 * 排序值+ID+筛选摘要；非法游标 400 INVALID_INPUT）。
 *
 * <p>编码 = URL-safe Base64(JSON {"k":排序值,"i":末位ID,"f":筛选摘要})。
 * 解码失败（非 Base64 / 非 JSON / 缺键）一律抛 {@link CursorException}。
 * B/C/D 列表端点直接复用。</p>
 */
@Component
public class CursorCodec {

    public static final int DEFAULT_LIMIT = 20;
    public static final int MAX_LIMIT = 100;

    private final ObjectMapper objectMapper;

    public CursorCodec(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    public record Cursor(String sortValue, String id, String filterDigest) {
    }

    public String encode(String sortValue, String id, String filterDigest) {
        try {
            var node = objectMapper.createObjectNode();
            node.put("k", sortValue);
            node.put("i", id);
            node.put("f", filterDigest);
            return Base64.getUrlEncoder().withoutPadding()
                    .encodeToString(objectMapper.writeValueAsBytes(node));
        } catch (Exception e) {
            throw new IllegalStateException("cursor encode failed", e);
        }
    }

    public Cursor decode(String cursor) {
        try {
            byte[] raw = Base64.getUrlDecoder().decode(cursor.getBytes(StandardCharsets.UTF_8));
            JsonNode node = objectMapper.readTree(raw);
            if (!node.isObject() || !node.hasNonNull("k") || !node.hasNonNull("i")) {
                throw new CursorException("cursor missing required members");
            }
            return new Cursor(node.get("k").asText(), node.get("i").asText(),
                    node.hasNonNull("f") ? node.get("f").asText() : "");
        } catch (CursorException e) {
            throw e;
        } catch (Exception e) {
            throw new CursorException("cursor is not a valid opaque token");
        }
    }

    /** 校验 limit：缺省 20，越界（&lt;1 或 &gt;100）由调用方转 400。 */
    public int normalizeLimit(Integer limit) {
        if (limit == null) return DEFAULT_LIMIT;
        if (limit < 1 || limit > MAX_LIMIT) {
            throw new CursorException("limit must be between 1 and 100");
        }
        return limit;
    }
}

package cn.yuanxin.mvp.web.idempotency;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;

/**
 * RFC 8785 (JCS) 序列化 + SHA-256 payload_hash（contracts/canonicalization.md）。
 *
 * <p><b>行为锁定基准是 backend/contracts/scripts/jcs.py</b>（跨语言唯一参考
 * 实现，两侧测试必须字节一致复现 samples/canonicalization/vectors.json 全部
 * 向量）。实现要点：</p>
 * <ul>
 *   <li>对象键按 UTF-16 code unit 升序（Java String.compareTo 即该顺序）；
 *       数组保持原序；无空白；</li>
 *   <li>字符串最小转义（" \ \b \t \n \f \r、&lt;0x20 → \u00xx 小写 hex），
 *       非 ASCII（中文等）原样 UTF-8 输出；孤立代理对拒绝；</li>
 *   <li>数字 ECMAScript Number::toString 风格；-0 → "0"；NaN/Infinity 拒绝；
 *       JSON 数字超过 2^53-1 拒绝（bigint 一律以字符串传输）；</li>
 *   <li>输入解析启用 Jackson STRICT_DUPLICATE_DETECTION——重复 JSON 键是
 *       错误而不是覆盖。</li>
 * </ul>
 *
 * <p><b>参考实现怪癖（字节兼容所需，勿"顺手修正"）</b>：jcs.py 的
 * _number_to_string 对 1e-4 ≤ |v| &lt; 1 的非整值 double 存在小数点定位缺陷
 * （0.5 → "5"、0.123 → "1.23"、0.0001 → "1"），vectors.json 的
 * small-numbers 向量哈希即按该行为生成。本实现忠实复现该边界，保证
 * Java/Python 对任意输入得到同一摘要；本项目契约数据不产生该区间数字
 * （计数/revision 是字符串、schema_version 是小整数），不受影响。
 * 该缺陷已上报总协调，待契约 lane 决定修订 jcs.py + 向量。</p>
 */
public final class Jcs {

    private static final BigInteger MAX_SAFE = BigInteger.valueOf(9007199254740991L);

    /** 严格 ObjectMapper：拒绝重复键、拒绝未知 token 之外的宽松行为。 */
    private static final ObjectMapper STRICT = new ObjectMapper()
            .enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION)
            .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);

    private Jcs() {
    }

    /** 解析 JSON 字符串；重复键/尾随内容/语法错误 → IllegalArgumentException。 */
    public static JsonNode parseStrict(String json) {
        try {
            JsonNode node = STRICT.readTree(json);
            if (node == null) {
                throw new IllegalArgumentException("empty JSON input");
            }
            return node;
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("invalid JSON input: " + e.getOriginalMessage(), e);
        }
    }

    /** 任意 Java 结构（Map/List/String/Integer/Long/Double/Boolean/null）→ JsonNode。 */
    public static JsonNode toNode(Object value) {
        JsonNode node = STRICT.valueToTree(value);
        if (node == null) {
            throw new IllegalArgumentException("value not convertible to JSON");
        }
        return node;
    }

    public static String canonicalize(JsonNode node) {
        StringBuilder sb = new StringBuilder();
        write(node, sb);
        return sb.toString();
    }

    public static byte[] canonicalizeBytes(JsonNode node) {
        return canonicalize(node).getBytes(StandardCharsets.UTF_8);
    }

    /** SHA-256(canonical UTF-8 字节)，小写 hex（无 "sha256:" 前缀；T13 列存裸 hex）。 */
    public static String sha256Hex(JsonNode node) {
        return sha256HexBytes(canonicalizeBytes(node));
    }

    public static String sha256HexBytes(byte[] bytes) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(md.digest(bytes));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 unavailable", e);
        }
    }

    // ---------------- serialization core ----------------

    private static void write(JsonNode n, StringBuilder o) {
        switch (n.getNodeType()) {
            case NULL -> o.append("null");
            case BOOLEAN -> o.append(n.booleanValue() ? "true" : "false");
            case NUMBER -> o.append(numberToString(n));
            case STRING -> appendString(n.textValue(), o);
            case ARRAY -> {
                o.append('[');
                for (int i = 0; i < n.size(); i++) {
                    if (i > 0) o.append(',');
                    write(n.get(i), o);
                }
                o.append(']');
            }
            case OBJECT -> {
                List<String> names = new ArrayList<>();
                n.fieldNames().forEachRemaining(names::add);
                names.sort(String::compareTo); // UTF-16 code-unit order (ES6 sort)
                o.append('{');
                for (int i = 0; i < names.size(); i++) {
                    if (i > 0) o.append(',');
                    appendString(names.get(i), o);
                    o.append(':');
                    write(n.get(names.get(i)), o);
                }
                o.append('}');
            }
            default -> throw new IllegalArgumentException(
                    "unsupported JSON value type: " + n.getNodeType());
        }
    }

    private static void appendString(String s, StringBuilder o) {
        o.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"' -> o.append("\\\"");
                case '\\' -> o.append("\\\\");
                case '\b' -> o.append("\\b");
                case '\t' -> o.append("\\t");
                case '\n' -> o.append("\\n");
                case '\f' -> o.append("\\f");
                case '\r' -> o.append("\\r");
                default -> {
                    if (Character.isHighSurrogate(c)) {
                        if (i + 1 >= s.length() || !Character.isLowSurrogate(s.charAt(i + 1))) {
                            throw new IllegalArgumentException(
                                    "lone surrogate U+" + Integer.toHexString(c) + " in string");
                        }
                        o.append(c).append(s.charAt(++i));
                    } else if (Character.isLowSurrogate(c)) {
                        throw new IllegalArgumentException(
                                "lone surrogate U+" + Integer.toHexString(c) + " in string");
                    } else if (c < 0x20) {
                        o.append("\\u").append(String.format("%04x", (int) c));
                    } else {
                        o.append(c); // 非 ASCII（含中文）原样输出
                    }
                }
            }
        }
        o.append('"');
    }

    /** 与 jcs.py::_number_to_string 一致的数字序列化（含其 |v|∈[1e-4,1) 边界行为）。 */
    static String numberToString(JsonNode n) {
        if (n.isIntegralNumber()) {
            BigInteger v = n.bigIntegerValue();
            if (v.abs().compareTo(MAX_SAFE) > 0) {
                throw new IllegalArgumentException(
                        "JSON number exceeds the safe double range; transport big integers as strings");
            }
            return v.toString();
        }
        if (n.isBigDecimal()) {
            // 本项目 JSON 不产生 BigDecimal 数字节点；按 double 规则拒绝越界值
            java.math.BigDecimal bd = n.decimalValue();
            if (bd.abs().compareTo(new java.math.BigDecimal(MAX_SAFE)) > 0) {
                throw new IllegalArgumentException("JSON number exceeds the safe double range");
            }
            return doubleToString(bd.doubleValue());
        }
        if (!n.isFloatingPointNumber()) {
            throw new IllegalArgumentException("unsupported number node: " + n.getNodeType());
        }
        double d = n.doubleValue();
        return doubleToString(d);
    }

    static String doubleToString(double d) {
        if (Double.isNaN(d) || Double.isInfinite(d)) {
            throw new IllegalArgumentException("NaN/Infinity are not serializable per RFC 8785");
        }
        if (d == 0.0) {
            return "0"; // 覆盖 -0
        }
        String sign = d < 0 ? "-" : "";
        double a = Math.abs(d);
        if (a == Math.rint(a) && a < 1e21) {
            return sign + Long.toString((long) a);
        }
        // 最短往返十进制（Java 21 Double.toString 与 Python repr 同为 Ryu 最短性）
        String s = Double.toString(a);
        int eIdx = s.indexOf('E');
        int exp10 = 0;
        if (eIdx >= 0) {
            exp10 = Integer.parseInt(s.substring(eIdx + 1));
            s = s.substring(0, eIdx);
        }
        int dot = s.indexOf('.');
        String intPart = dot < 0 ? s : s.substring(0, dot);
        String fracPart = dot < 0 ? "" : s.substring(dot + 1);
        String digits = (intPart + fracPart).replaceFirst("^0+", "");
        if (digits.isEmpty()) digits = "0";
        digits = digits.replaceFirst("0+$", "");
        if (digits.isEmpty()) digits = "0";
        int nPos = intPart.length() + exp10; // value == 0.digits' * 10**nPos（未剥前导零前）
        // jcs.py 行为：Python repr 对 [1e-4,1) 用普通小数 "0.xxx"，剥前导零后 n 固定为 1。
        // Java Double.toString 在 [1e-4,1e-3) 已进指数形（nPos 会算成 ≤-2），须按
        // 参考实现结果对齐：该区间 jcs.py 恒得 n=1。
        if (a >= 1e-4 && a < 1.0) {
            nPos = 1;
        }
        int k = digits.length();
        if (k <= nPos && nPos <= 21) {
            return sign + digits + "0".repeat(nPos - k);
        }
        if (0 < nPos && nPos <= 21) {
            return sign + digits.substring(0, nPos) + "." + digits.substring(nPos);
        }
        if (-6 < nPos && nPos <= 0) {
            return sign + "0." + "0".repeat(-nPos) + digits;
        }
        String m = (k == 1) ? digits : digits.charAt(0) + "." + digits.substring(1);
        int e = nPos - 1;
        return sign + m + (e >= 0 ? "e+" : "e-") + Math.abs(e);
    }

    /** 便捷：从字段顺序无关的 Map 构造 canonical SHA-256。 */
    public static String sha256HexOfObject(Object javaStructure) {
        JsonNode root = toNode(javaStructure);
        if (!root.isObject()) {
            throw new IllegalArgumentException("canonical object must be a JSON object");
        }
        return sha256Hex(root);
    }

    /** 单元测试辅助：返回 canonical ObjectNode（键序无关）。 */
    public static ObjectNode objectNode() {
        return STRICT.createObjectNode();
    }

    public static ArrayNode arrayNode() {
        return STRICT.createArrayNode();
    }
}

